# WAR ARENA - API Wiring Layer (auth + billing + consent + webhooks) + .gitignore
# Connects the built layers through HTTP: auth enforced, /scan charges balance,
# /me + /consent + payment webhooks. Run from project root:
#   powershell -ExecutionPolicy Bypass -File .\install-wiring.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - API Wiring installer" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/api/wiredApp.ts" ""
Write-B64 "src/api/router.ts" ""
Write-B64 "src/api/httpServer.ts" ""
Write-B64 "src/integration/warRuntime.ts" ""
Write-B64 "src/deploy/server.ts" ""
Write-B64 "tests/integration/wiredApi.test.ts" ""
Write-B64 ".gitignore" "bm9kZV9tb2R1bGVzCmRpc3QKLmVudgouZW52LioKIS5lbnYuZXhhbXBsZQoqLnBlbQoqLmtleQpfYmFja3VwLSoKKi5sb2cKLkRTX1N0b3JlCmNvdmVyYWdlCi5nbWduLXByb2JlLm10cwo="

Write-Host ""; Write-Host "Verifying gate ..." -ForegroundColor Cyan
npx tsc --noEmit; if ($LASTEXITCODE -ne 0){ throw "typecheck failed" }
npx vitest run
